package com.bank.compression;

import org.apache.kafka.clients.producer.*;
import org.apache.kafka.common.serialization.StringSerializer;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class CompressionDemo {
    private static final Logger log = Logger.getLogger(CompressionDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // The same repetitive JSON payload, published under each codec.
        List<String> payload = buildBatch();   // many similar TxnEvents
        long rawBytes = payload.stream().mapToLong(s -> s.getBytes().length).sum();
        log.info(() -> String.format("Raw payload size: %,d bytes", rawBytes));

        // Try each codec. In production you pick ONE and let the broker keep it.
        for (String codec : List.of("none", "snappy", "lz4", "gzip", "zstd")) {
            publishWith(codec, payload);
        }

        log.info("Guidance: gzip = tightest but high CPU; snappy/lz4 = fast, looser; "
               + "zstd = strong ratio + good speed (modern default). Let the broker "
               + "keep the producer codec (compression.type=producer) to avoid recompress.");
    }

    private static void publishWith(String codec, List<String> payload) {
        Properties p = new Properties();
        p.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, "broker1:9092");
        p.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        p.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        p.put(ProducerConfig.ACKS_CONFIG, "all");
        p.put(ProducerConfig.COMPRESSION_TYPE_CONFIG, codec);   // the knob under test
        p.put(ProducerConfig.LINGER_MS_CONFIG, 20);             // let the batch fill
        p.put(ProducerConfig.BATCH_SIZE_CONFIG, 131_072);

        try (Producer<String, String> producer = new KafkaProducer<>(p)) {
            for (String value : payload) {
                String account = value.contains("SAV2001") ? "SAV2001" : "CUR3001";
                producer.send(new ProducerRecord<>("transactions", account, value));
            }
            producer.flush();
            log.info(() -> "Published batch with compression.type=" + codec);
        } catch (Exception e) {
            log.log(Level.SEVERE, "Publish failed for codec " + codec, e);
        }
    }

    private static List<String> buildBatch() {
        List<String> list = new ArrayList<>();
        for (int i = 0; i < 10_000; i++) {
            String account = (i % 2 == 0) ? "SAV2001" : "CUR3001";
            list.add(new TxnEvent(account, new BigDecimal("50000"), i).toJson());
        }
        return list;
    }
}

// ─── Would be in model/TxnEvent.java in a real project ───
class TxnEvent {
    private final String account;
    private final BigDecimal amount;
    private final long seq;
    TxnEvent(String account, BigDecimal amount, long seq) {
        this.account = account; this.amount = amount; this.seq = seq;
    }
    String toJson() {
        return "{\"account\":\"" + account + "\",\"amount\":" + amount
             + ",\"seq\":" + seq + ",\"type\":\"RENT_CREDIT\"}";
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
